import heapq

def pass_route(n: int, edges: list[list[int]], stations: list[list[int]], prices: list[int]) -> int:
    k = len(prices)
    adj = [[] for _ in range(n)]
    for u, v, c, z in edges:
        adj[u].append((v, c, z))
        adj[v].append((u, c, z))
    st = [set() for _ in range(n)]
    for s, z in stations:
        if 0 <= s < n and 0 <= z < k:
            st[s].add(z)
    M = 1 << k
    INF = float('inf')
    dist = [[INF] * M for _ in range(n)]
    dist[0][0] = 0
    pq = [(0, 0, 0)]
    target = n - 1
    while pq:
        d, u, m = heapq.heappop(pq)
        if d > dist[u][m]:
            continue
        if u == target:
            return d
        for z in st[u]:
            if not (m >> z) & 1:
                nm = m | (1 << z)
                nd = d + prices[z]
                if nd < dist[u][nm]:
                    dist[u][nm] = nd
                    heapq.heappush(pq, (nd, u, nm))
        du = dist[u]
        for v, c, z in adj[u]:
            if z >= 0 and (m >> z) & 1:
                nd = d
            else:
                nd = d + c
            if nd < dist[v][m]:
                dist[v][m] = nd
                heapq.heappush(pq, (nd, v, m))
    return -1
